/**
 * The exact Rezmancer page: public/resume/snapshot.json (every word's box and style)
 * plus text.webp (the glyphs on transparent) and decor.webp (bullets, tint bars, rules).
 * Generated by docs/design/jelly-resume/tools/snapshot.mjs --web; it has no phone or email.
 */

export type WordKind = 'heading' | 'bold' | 'body'

export interface SnapshotWord {
  t: string
  x: number
  y: number
  w: number
  h: number
  color: string
  size: number
  weight: string
  kind: WordKind
}

export interface Snapshot {
  source: string
  dpr: number
  /** Letter, in inches */
  page: { w: number; h: number; marginX: number; marginY: number }
  /** CSS px */
  content: { w: number; h: number }
  images: { text: string; decor: string }
  words: SnapshotWord[]
}

/** One jelly body to build: position and size in page units (1 = 1 inch = 96 CSS px). */
export interface BodySpec {
  text: string
  x: number
  w: number
  line: { top: number; lh: number }
  st: { kind: WordKind; color: string; wt: number; fs: number }
  /** where its glyphs are in text.webp, in image px */
  crop: { x: number; y: number; w: number; h: number }
}

const isNum = (v: unknown): v is number => typeof v === 'number' && Number.isFinite(v)

export function parseSnapshot(raw: unknown): Snapshot {
  const s = raw as Partial<Snapshot> | null
  const ok =
    !!s &&
    isNum(s.dpr) &&
    !!s.page && isNum(s.page.w) && isNum(s.page.h) && isNum(s.page.marginX) && isNum(s.page.marginY) &&
    !!s.content && isNum(s.content.w) && isNum(s.content.h) &&
    !!s.images && typeof s.images.text === 'string' && typeof s.images.decor === 'string' &&
    Array.isArray(s.words) && s.words.length > 0 &&
    s.words.every((w) => w && typeof w.t === 'string' && isNum(w.x) && isNum(w.y) && isNum(w.w) && isNum(w.h) && isNum(w.size))
  if (!ok) throw new Error('Not a Jelly Resume snapshot')
  return s as Snapshot
}

/** 'rgb(15, 118, 110)' → '#0f766e' */
export const rgbHex = (c: string) =>
  '#' + (c.match(/\d+(\.\d+)?/g) || ['0', '0', '0']).slice(0, 3).map((v) => Math.round(+v).toString(16).padStart(2, '0')).join('')

/** Snapshot words → body specs (the shape the playground's runtime layout produced). */
export function snapshotBodies(snap: Snapshot): BodySpec[] {
  const S = 1 / 96, ox = snap.page.marginX, oy = snap.page.marginY, D = snap.dpr
  return snap.words.map((w) => ({
    text: w.t,
    x: ox + w.x * S,
    w: w.w * S,
    line: { top: -(oy + w.y * S), lh: w.h * S },
    st: { kind: w.kind, color: rgbHex(w.color), wt: +w.weight || 400, fs: w.size * S },
    crop: { x: w.x * D, y: w.y * D, w: w.w * D, h: w.h * D },
  }))
}

export interface LoadedSnapshot {
  snap: Snapshot
  text: HTMLImageElement
  decor: HTMLImageElement
}

const loadImage = (src: string) => {
  const img = new Image()
  img.decoding = 'async'
  img.src = src
  return img.decode().then(() => img)
}

/** Fetch the snapshot and decode both layers. `base` is the folder they're served from. */
export async function loadSnapshot(base = '/resume/'): Promise<LoadedSnapshot> {
  const res = await fetch(base + 'snapshot.json')
  if (!res.ok) throw new Error(`Snapshot request failed: ${res.status}`)
  const snap = parseSnapshot(await res.json())
  const [text, decor] = await Promise.all([loadImage(base + snap.images.text), loadImage(base + snap.images.decor)])
  return { snap, text, decor }
}
